"""The vendor artifact: taf-runtime/ — the SUT-agnostic engine
(TypeScript). makeTafTest() builds the fixture layer; the suite feeds
it base-url + sign-in through its own sut.config.ts.
"""

import os

from .common import _HEADER
from .runtime import _journal_source, _sink_source


_FW_HEADER = "// Generated by tafbase (taf emit-framework --lang ts). " \
             "Do not edit.\n"


_PACKAGE_JSON = """{
  "name": "@tafbase/runtime",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Generated tafbase framework runtime — Playwright fixtures, journal, visual comparator, api client",
  "devDependencies": {
    "@playwright/test": "^1.49.0",
    "@types/node": "^22.0.0",
    "typescript": "^5.6.0"
  }
}
"""


_SOFT_CHECKS = _FW_HEADER + """// @concept CONCEPT-testing-v1-002-01-the-failure-funnel

export class SoftChecks {
  readonly failures: string[] = [];

  async check(label: string, fn: () => Promise<void> | void): Promise<void> {
    try {
      await fn();
    } catch (e: any) {
      this.failures.push(`${label} — ${e?.message ?? e}`);
    }
  }

  assertAll(): void {
    if (this.failures.length > 0) {
      throw new Error(`${this.failures.length} soft check(s) failed: ${this.failures.join("; ")}`);
    }
  }

  flush(): void {
    this.assertAll();
  }
}
"""


_API_CLIENT = _FW_HEADER + """// @concept CONCEPT-testing-v1-009-01-the-api-oracle

import { APIRequestContext, request as pwRequest } from "@playwright/test";

/** A thin wrapper over APIRequestContext — the browserless request
 * side of the framework. api journeys use playwright's built-in
 * `request` fixture directly; ApiClient is the call seam for hand
 * tests that need an owned context. */
export class ApiClient {
  constructor(readonly ctx: APIRequestContext) {}
  raw(): APIRequestContext { return this.ctx; }
}

export async function newRequestContext(): Promise<APIRequestContext> {
  return pwRequest.newContext();
}
"""


_VISUAL = _FW_HEADER + """// @concept CONCEPT-taf-v1-004-01-the-artifacts

import * as fs from "node:fs";
import * as path from "node:path";
import { Locator, Page } from "@playwright/test";
import { tafJournal } from "./taf_journal";

interface Row { name: string; status: string; expected: string; actual: string; }
const ROWS: Row[] = [];

export function goldensDir(): string {
  return process.env["TAF_GOLDENS"] || "@@golden@@";
}

function diffHtml(name: string, expected: string, actual: string): string {
  return `<!doctype html><meta charset=utf-8><title>diff ${name}</title>`
    + `<h2>${name}</h2><table><tr><th>Expected</th><th>Actual</th></tr><tr>`
    + `<td><img src="file://${expected}" style="max-width:48vw"></td>`
    + `<td><img src="file://${actual}" style="max-width:48vw"></td>`
    + `</tr></table>`;
}

/** Screenshot → <test>/<name>_Actual.png; assert byte-equality with the
 * <name>_Expected.png baseline. `taf promote` approves a new baseline. */
export async function compare(page: Page, name: string,
                              opts?: { mask?: Locator[] }): Promise<void> {
  const d = tafJournal.testDir();
  const actual = path.join(d, `${name}_Actual.png`);
  await page.screenshot({ path: actual, mask: opts?.mask });
  const expected = path.join(goldensDir(), `${name}_Expected.png`);
  if (!fs.existsSync(expected)) {
    ROWS.push({ name, status: "no-baseline", expected, actual });
    tafJournal.event("visual", { name, outcome: "no-baseline" });
    throw new Error(
      `no baseline for '${name}' — inspect ${actual} then \\`taf promote\\` approves it`);
  }
  if (fs.readFileSync(actual).equals(fs.readFileSync(expected))) {
    ROWS.push({ name, status: "ok", expected, actual });
    tafJournal.event("visual", { name, outcome: "ok" });
    return;
  }
  const diff = path.join(d, `${name}_Diff.html`);
  fs.writeFileSync(diff, diffHtml(name, expected, actual), "utf-8");
  ROWS.push({ name, status: "diff", expected, actual });
  tafJournal.event("visual", { name, outcome: "diff" });
  throw new Error(
    `screenshot '${name}' differs from the baseline — see ${diff}; ` +
    `\\`taf promote\\` approves the new image`);
}

/** The run's side-by-side report — visual-report.html in the run dir. */
export function writeReport(runDir: string): string | null {
  if (ROWS.length === 0) return null;
  const rows = ROWS.map(r =>
    `<tr><td>${r.name}</td><td>${r.status}</td>`
    + `<td><a href="file://${r.expected}">expected</a></td>`
    + `<td><a href="file://${r.actual}">actual</a></td></tr>`).join("");
  const p = path.join(runDir, "visual-report.html");
  fs.writeFileSync(p,
    `<!doctype html><meta charset=utf-8><title>visual report</title>`
    + `<h2>visual comparisons</h2><table border=1>`
    + `<tr><th>name</th><th>status</th><th>expected</th><th>actual</th></tr>${rows}</table>`,
    "utf-8");
  return p;
}

/** Approve Actual images under resultsDir as Expected baselines. */
export function promote(resultsDir: string, goldens: string): string[] {
  fs.mkdirSync(goldens, { recursive: true });
  const moved: string[] = [];
  const walk = (dir: string) => {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      const p = path.join(dir, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.name.endsWith("_Actual.png")) {
        const dst = path.join(goldens,
          e.name.slice(0, -"_Actual.png".length) + "_Expected.png");
        fs.copyFileSync(p, dst);
        moved.push(dst);
      }
    }
  };
  walk(resultsDir);
  return moved;
}
"""


def _framework_fixtures():
    """taf-runtime/fixtures.ts — makeTafTest(): the fixture layer as a
    factory over { baseUrl, signIn }."""
    return _FW_HEADER + """// @concept CONCEPT-pwtest-v1-001-01-test-extend-fixtures
// @concept CONCEPT-ts-v1-006-01-typed-test-fixture-extension
// @concept CONCEPT-ts-v1-010-01-typed-env-config
// @concept CONCEPT-playwright-v1-001-01-browser-context-page-hierarchy
// @concept CONCEPT-taf-v1-003-01-the-environment
// @concept CONCEPT-taf-v1-004-01-the-artifacts
// @concept CONCEPT-testing-v1-002-01-the-failure-funnel
// @concept CONCEPT-testing-v1-004-01-the-rerun
// @concept CONCEPT-taf-v1-002-01-the-result-sink
// @concept CONCEPT-dsl-v1-016-01-the-auth-clause
// @concept CONCEPT-playwright-v1-008-01-storage-state-reuse

import * as fs from "node:fs";
import * as path from "node:path";
import { test as base, expect, Page, Browser, BrowserContext } from "@playwright/test";
import { tafJournal } from "./taf_journal";
import * as ikc3Sink from "./ikc3_sink";
import { SoftChecks } from "./soft-checks";
import * as visual from "./visual";

export { SoftChecks };

function makeRunDir(): string {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, "0");
  const stamp = `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
  return path.join(process.env["TAF_RESULTS"] || "results", stamp);
}

const FAILED_TESTS: string[] = [];

function getLastFailed(): Set<string> | null {
  try {
    const resultsRoot = process.env["TAF_RESULTS"] || "results";
    if (!fs.existsSync(resultsRoot)) return null;
    const entries = fs.readdirSync(resultsRoot, { withFileTypes: true })
      .filter((e) => e.isDirectory())
      .map((e) => path.join(resultsRoot, e.name, "@@failed@@"))
      .filter((p) => fs.existsSync(p))
      .sort();
    if (entries.length === 0) return null;
    const latest = entries[entries.length - 1];
    const lines = fs.readFileSync(latest, "utf-8").trim().split(/\\s+/).filter(Boolean);
    return new Set(lines);
  } catch {
    return null;
  }
}

export interface TafConfig {
  /** The model's base-url — TAF_BASE_URL overrides it at run time. */
  baseUrl: string;
  /** One sign-in in a bootstrap context; kept as storage state. */
  signIn?: ((page: Page, baseUrl: string) => Promise<void>) | null;
}

export interface TafFixtures {
  baseUrl: string;
  soft: SoftChecks;
  journal: null;
}

/** Build the suite's test object. Everything the framework needs to
 * know about the SUT arrives through config — the vendor artifact
 * never names a SUT. */
export function makeTafTest(config: TafConfig) {
  const runDir = makeRunDir();
  const baseUrl = process.env["TAF_BASE_URL"] || config.baseUrl;
  const headless = process.env["TAF_HEADLESS"] === "1";
  const slowmo = process.env["TAF_SLOWMO"] || "0";
  const video = process.env["TAF_VIDEO"] ? "on" : "off";
  const arriveMs = process.env["TAF_ARRIVE_MS"] || "15000";

  console.log(
    `taf env: base_url=${baseUrl} headless=${headless} slowmo=${slowmo} video=${video} arrive_ms=${arriveMs} results=${runDir}`
  );

  process.on("exit", () => {
    try {
      fs.mkdirSync(runDir, { recursive: true });
      fs.writeFileSync(path.join(runDir, "@@failed@@"), FAILED_TESTS.join("\\n") + (FAILED_TESTS.length ? "\\n" : ""), "utf-8");
      const report = visual.writeReport(runDir);
      if (report) console.log("visual report → " + report);
      console.log("\\nresults → " + runDir);
      if (FAILED_TESTS.length > 0) {
        console.log("failed → " + FAILED_TESTS.join(", ") + "  (rerun: TAF_RERUN=1 npx playwright test)");
      }
    } catch (_ignored) {}
  });

  let authStatePath: string | null = null;

  async function performAuthOnce(browser: Browser, targetBaseUrl: string): Promise<string> {
    if (authStatePath) return authStatePath;
    const storagePath = path.join(runDir, "@@auth-state@@");
    const ctx = await browser.newContext();
    const pg = await ctx.newPage();
    try {
      await config.signIn!(pg, targetBaseUrl);
    } catch (err) {
      const setupDir = path.join(runDir, "setup");
      fs.mkdirSync(setupDir, { recursive: true });
      try {
        const dom = await pg.content();
        fs.writeFileSync(path.join(setupDir, "@@dom@@"), dom, "utf-8");
        await pg.screenshot({ path: path.join(setupDir, "@@screenshot@@") });
      } catch (_ignored) {}
      if (process.env["TAF_DEBUG"] === "1") {
        await pg.pause();
      }
      await ctx.close();
      throw err;
    }
    await ctx.storageState({ path: storagePath });
    await ctx.close();
    authStatePath = storagePath;
    return storagePath;
  }

  const test = base.extend<TafFixtures>({
    baseUrl: async ({}, use) => {
      await use(baseUrl);
    },
    soft: async ({}, use) => {
      const s = new SoftChecks();
      await use(s);
      s.assertAll();
    },
    journal: [async ({}, use, testInfo) => {
      if (process.env["TAF_RERUN"] === "1") {
        const lastFailed = getLastFailed();
        if (lastFailed && !lastFailed.has(testInfo.title)) {
          testInfo.skip(true, "TAF_RERUN: not in last @@failed@@");
          return;
        }
      }
      tafJournal.begin(runDir, testInfo.title);
      await use(null);
      const isFailed = testInfo.status !== testInfo.expectedStatus;
      if (isFailed) {
        FAILED_TESTS.push(testInfo.title);
        tafJournal.event("fail", { test: testInfo.title });
      }
      tafJournal.end(isFailed ? "failed" : "passed");
    }, { auto: true }],
    context: async ({ browser }, use) => {
      let authStorage: string | undefined = undefined;
      if (config.signIn) {
        authStorage = await performAuthOnce(browser, baseUrl);
      }
      const contextOptions: any = {};
      if (authStorage) {
        contextOptions.storageState = authStorage;
      }
      if (process.env["TAF_VIDEO"] === "1") {
        contextOptions.recordVideo = { dir: tafJournal.testDir() };
      }
      const ctx = await browser.newContext(contextOptions);
      await use(ctx);
      await ctx.close();
    },
    page: async ({ context, journal }, use, testInfo) => {
      const pg = await context.newPage();
      let failed = false;
      try {
        await use(pg);
      } catch (err) {
        failed = true;
        throw err;
      } finally {
        const isFailed = testInfo.status !== testInfo.expectedStatus || failed;
        if (isFailed) {
          const d = tafJournal.testDir();
          try {
            await pg.screenshot({ path: path.join(d, "@@screenshot@@") });
            const dom = await pg.content();
            fs.writeFileSync(path.join(d, "@@dom@@"), dom, "utf-8");
          } catch (_ignored) {}
          const wsUrl = process.env["TAF_IKC3_WS"];
          if (wsUrl) {
            try {
              const errStr = (testInfo.error?.message || "test failed").split("\\n")[0].slice(0, 200);
              const fp = ikc3Sink.fingerprint(testInfo.title, errStr);
              const old = ikc3Sink.filed(fp);
              if (old) {
                console.log(`fault report already filed: ${old} (fp ${fp})`);
                tafJournal.note(`fault report already filed: ${old}`);
              } else {
                const rid = await ikc3Sink.fileReport(
                  wsUrl,
                  `taf journey failed: ${testInfo.title} — ${errStr}`,
                  { url: pg.url(), dom: await pg.content().catch(() => "") }
                );
                ikc3Sink.record(fp, rid);
                console.log("fault report filed:", rid);
              }
            } catch (sinkErr) {
              console.log("ikc3 sink could not file the report:", sinkErr);
            }
          }
          if (process.env["TAF_DEBUG"] === "1") {
            await pg.pause();
          }
        }
      }
    },
  });

  return { test, expect };
}
"""


def framework_files():
    """path → source for the whole vendor package (@@artifact@@ tokens
    resolved by the caller)."""
    return {
        "package.json": _PACKAGE_JSON,
        "taf_journal.ts": _journal_source(),
        "ikc3_sink.ts": _sink_source(),
        "soft-checks.ts": _SOFT_CHECKS,
        "api-client.ts": _API_CLIENT,
        "visual.ts": _VISUAL,
        "fixtures.ts": _framework_fixtures(),
    }
